const input = $input.first().json;

const execution = input.execution || {};
const workflow = input.workflow || {};
const error = execution.error || input.error || {};

const now = new Date().toISOString();

// Giữ correlation_id cũ nếu workflow nguồn đã có.
// Nếu chưa có thì tạo UUID v4 mới để phục vụ tracing.
const correlationId =
  execution.data?.correlation_id ||
  input.correlation_id ||
  'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });

return [
  {
    json: {
      workflow_name: workflow.name || 'Unknown Workflow',
      workflow_id: workflow.id || null,

      execution_id: execution.id || null,
      execution_url: execution.url || null,

      failed_node:
        execution.lastNodeExecuted ||
        error.node?.name ||
        'Unknown Node',

      error_message:
        error.message ||
        execution.error?.message ||
        'Unknown error',

      error_name:
        error.name ||
        execution.error?.name ||
        'Error',

      error_stack:
        error.stack ||
        execution.error?.stack ||
        null,

      correlation_id: correlationId,

      status: 'FAILED',
      retry_count: 0,
      occurred_at: now
    }
  }
];

