parameters.jsCode:
const data = $('Authentication').item.json;

const message = String(data.error_message || '').toLowerCase();

const retryableKeywords = [
  'timeout',
  'timed out',
  'connection',
  'network',
  'econnreset',
  'econnrefused',
  'socket',
  '503',
  '502',
  '504',
  '429',
  'rate limit',
  'service unavailable'
];

const isRetryable = retryableKeywords.some(keyword =>
  message.includes(keyword)
);

return [
  {
    json: {
      ...data,
      retryable: isRetryable,
      severity: isRetryable ? 'HIGH' : 'CRITICAL',
      alert_required: true,
      analyzed_at: new Date().toISOString()
    }
  }
];
